"""IncidentLens reviewed, read-only-first troubleshooting runbooks.
No commands are executed by this module. Operators must verify environment and approvals.
"""
from dataclasses import dataclass

@dataclass(frozen=True)
class Guide:
    id: str
    title: str
    why: str
    steps: tuple[str, ...]
    commands: tuple[str, ...] = ()
    category: str = 'web_access'

GUIDES = {}
CATEGORY_GUIDES = {}

def add(category, key, title, why, steps, commands=()):
    GUIDES[key] = Guide(key, title, why, tuple(steps), tuple(commands), category)
    CATEGORY_GUIDES[category] = CATEGORY_GUIDES.get(category, ()) + (key,)

add('container', 'k8s_crash', 'Kubernetes: CrashLoopBackOff ve uygulama çökmesi', 'Container başlıyor ancak kısa süre sonra sonlanıyor olabilir. CrashLoopBackOff kök neden değil, yeniden başlatma döngüsünün belirtisidir.', ('Önce namespace ve pod adını belirle. kubectl get pods -A çıktısında STATUS, RESTARTS ve AGE sütunlarını incele.', 'kubectl describe pod POD_ADI -n NAMESPACE komutunda Last State, Reason, Exit Code ve Events alanlarını oku. ImagePullBackOff ile CrashLoopBackOff aynı sorun değildir.', 'kubectl logs POD_ADI -n NAMESPACE --previous komutuyla bir önceki çöken container logunu incele. Çok container varsa -c CONTAINER_ADI ekle.', 'Exception, missing configuration, connection refused veya authentication failed gibi ilk gerçek hata satırını belirle; gizli bilgileri ticket içine yapıştırma.', 'Kök neden doğrulanmadan pod silme, rollout restart veya production değişikliği yapma. Yapılandırma düzeltmesini değişiklik süreciyle uygula.'), ('kubectl get pods -A', 'kubectl describe pod POD_ADI -n NAMESPACE', 'kubectl logs POD_ADI -n NAMESPACE --previous'))

add('container', 'k8s_oom', 'Kubernetes: OOMKilled / bellek sınırı', 'Container bellek limitini aştığında işletim sistemi tarafından sonlandırılabilir.', ('Pod describe çıktısında Last State > Terminated > Reason alanının OOMKilled olup olmadığını kontrol et.', 'Exit Code 137 görülebilir ancak tek başına OOMKilled kanıtı değildir; Reason ve olaylarla doğrula.', 'Metrics Server kuruluysa kubectl top pod POD_ADI -n NAMESPACE ile anlık bellek kullanımını kontrol et; anlık değer geçmişteki tepe tüketimi göstermez.', 'Deployment resource requests/limits değerlerini incele; son sürümde bellek tüketimi artmış mı karşılaştır.', 'Bellek sızıntısı veya yetersiz limit tespit edilirse uygulama sahibiyle onaylı iyileştirme planı oluştur.'), ('kubectl describe pod POD_ADI -n NAMESPACE', 'kubectl top pod POD_ADI -n NAMESPACE', 'kubectl get deployment DEPLOYMENT_ADI -n NAMESPACE -o yaml'))

add('container', 'k8s_probe', 'Kubernetes: liveness / startup probe', 'Başarısız liveness kontrolü container yeniden başlatılmasına neden olabilir. Readiness başarısızlığı tek başına restart yaptırmaz.', ('kubectl describe pod çıktısının Events bölümünde Liveness probe failed veya Startup probe failed olaylarını ara.', 'Probe türünü (HTTP, TCP, exec), hedef portu ve path değerini deployment tanımından incele.', 'initialDelaySeconds, timeoutSeconds, failureThreshold ve startupProbe ayarlarını uygulamanın gerçek başlangıç süresiyle karşılaştır.', 'Probe hatasını uygulama loglarıyla eşleştir. Readiness başarısızlığını CrashLoopBackOff kök nedeni olarak varsayma.', 'Probe ayarlarını rastgele gevşetme; doğrulanan düzeltmeyi onaylı deployment ile uygula.'), ('kubectl describe pod POD_ADI -n NAMESPACE', 'kubectl get deployment DEPLOYMENT_ADI -n NAMESPACE -o yaml'))

add('container', 'k8s_dependency', 'Kubernetes: bağımlı servis veya yapılandırma hatası', 'Uygulama başlarken veritabanına, API servisine veya gerekli ayarlara ulaşamıyor olabilir.', ('Önceki container loglarında DNS failure, connection refused, timeout veya authentication failed kayıtlarını incele.', 'Kullanılan Service adını ve namespace bilgisini kontrol et; servis uç noktaları var mı salt-okunur komutlarla doğrula.', 'ConfigMap ve Secret referanslarının adlarını kontrol et; Secret değerlerini görüntüleme veya ticket içine kopyalama.', 'NetworkPolicy, servis sağlığı ve uygulama başlangıç sırası için ilgili ekiplerle karşılaştırma yap.', 'Doğrulanmış yapılandırma sorununu onaylı süreçle düzelt; gizli anahtarları değiştirmeden önce etki analizi yap.'), ('kubectl get svc -n NAMESPACE', 'kubectl get endpoints -n NAMESPACE', 'kubectl describe pod POD_ADI -n NAMESPACE'))

add('container', 'k8s_image', 'Kubernetes: image, entrypoint ve deployment', 'Yanlış imaj etiketi, entrypoint veya çalıştırma parametreleri container açılışını engelleyebilir.', ('Pod Events içinde ErrImagePull, ImagePullBackOff veya failed to start container ifadelerini ayırt et.', 'Pod describe çıktısındaki image, command ve args alanlarını onaylı deployment manifestiyle karşılaştır.', 'Son başarılı sürüm ile son değişiklik zamanını kaydet; image registry erişimini yetkili konsoldan kontrol et.', 'İmajı rastgele değiştirme veya rollback yapma. Değişiklik sahibinden doğrulama ve onay iste.'), ('kubectl describe pod POD_ADI -n NAMESPACE', 'kubectl rollout history deployment/DEPLOYMENT_ADI -n NAMESPACE'))

add('vpn', 'vpn_auth', 'VPN: kimlik doğrulama ve Permission Denied', 'Yanlış kimlik bilgisi, kilitli hesap, MFA veya VPN erişim politikası bağlantıyı reddedebilir.', ('VPN ürününü, tam hata kodunu, kullanıcıyı ve saat bilgisini kaydet; parola veya MFA kodu isteme.', 'İnternet bağlantısı VPN olmadan çalışıyor mu kontrol et. İnternetin çalışması VPN yetkisinin doğru olduğunu kanıtlamaz.', 'Yetkili konsoldan başarısız kimlik doğrulama kaydını incele; account locked, invalid credentials, MFA denied veya policy denied ayrımını yap.', 'AD hesabının etkinliğini ve VPN erişim grubunu kontrol et; benzer yetkili kullanıcıyla karşılaştır.', 'Parola sıfırlama, hesap kilidi açma veya grup ekleme işlemlerini yalnızca kimlik doğrulama ve onay sonrasında yap.'), ('ipconfig /all', 'whoami /groups'))

add('vpn', 'vpn_network', 'VPN: bağlantı yolu ve istemci', 'DNS, istemci sürümü, sertifika veya kurumsal ağ kısıtı tünel kurulmasını engelleyebilir.', ('VPN istemcisinin sürümünü ve tam bağlantı aşamasını not et: sunucuya erişim mi, oturum açma mı, tünel kurulumu mu?', 'VPN ağ geçidinin adının DNS ile çözümlendiğini kontrol et. TCP port testi yalnızca TCP tabanlı bağlantılar için anlamlıdır.', 'Başka bir ağ üzerinden kontrollü test yap; sorunun yalnızca belirli ağda oluşup oluşmadığını karşılaştır.', 'Sertifika tarihi, saat senkronizasyonu ve istemci loglarını yetkili araçlarla incele.', 'Firewall kuralı veya VPN profili değiştirmeden önce güvenlik ve ağ ekiplerinden onay al.'), ('nslookup VPN_GATEWAY_ADI', 'ipconfig /all'))

add('account', 'ad_lock', 'Active Directory: hesap kilidi / parola süresi', 'Yanlış parola denemeleri, eski kayıtlı kimlik bilgileri veya parola politikası hesabı etkileyebilir.', ('Kullanıcının aldığı tam oturum açma mesajını ve zamanı kaydet.', 'ADUC Account sekmesinde hesap etkin mi, kilitli mi, parola süresi dolmuş mu kontrol et.', 'Yetkiliysen domain controller Security loglarında 4740 kilitlenme olayını araştır; hangi cihazdan geldiğini doğrula.', 'Kayıtlı eski parola kullanan servis, mobil cihaz veya zamanlanmış görev olasılığını incele.', 'Kimlik doğrulaması ve onay olmadan parola sıfırlama veya hesap kilidi açma.'), ('whoami /upn', 'gpresult /r'))

add('account', 'ad_dc', 'Active Directory: domain controller ve oturum açma', 'DNS veya domain controller erişimi kesintisi etki alanı oturumunu engelleyebilir.', ('İstemcinin IP, DNS sunucusu ve saat bilgilerini kontrol et.', 'Domain controller keşfini ve DNS SRV kayıtlarını doğrula; yalnızca ping sonucuna güvenme.', 'Aynı OU veya lokasyondaki diğer kullanıcıları karşılaştır; tek cihaz mı yaygın kesinti mi ayır.', 'DC servislerine müdahale etmeden önce ilgili sistem yöneticisine bulguları ilet.'), ('ipconfig /all', 'nltest /dsgetdc:DOMAIN_ADI', 'nslookup -type=SRV _ldap._tcp.dc._msdcs.DOMAIN_ADI'))

add('permission', 'share_ntfs', 'Windows: paylaşım ve NTFS erişim reddi', 'Share ve NTFS izinleri ile grup üyeliklerinin birleşimi erişimi sınırlayabilir.', ('UNC yolunu, kullanıcıyı ve tam Access Denied mesajını kaydet.', 'Aynı klasöre farklı yetkili kullanıcı erişebiliyor mu karşılaştır.', 'AD grup üyeliklerini ve yeni üyelik sonrası oturum yenilenmesi gerekip gerekmediğini incele.', 'Sunucuda Sharing, Security ve Effective Access bölümlerini ayrı ayrı kontrol et.', 'İzinleri genişletmeden önce en az yetki ilkesini ve değişiklik onayını uygula.'), ('whoami /groups', 'net use'))

add('permission', 'linux_acl', 'Linux: Permission denied / dosya izinleri', 'Sahiplik, grup, POSIX izinleri, ACL veya SELinux/AppArmor erişimi engelleyebilir.', ('Hatanın hangi kullanıcı, komut ve tam dosya yolunda oluştuğunu belirle.', 'ls -ld ve namei -l ile yol üzerindeki dizin geçiş izinlerini kontrol et.', 'getfacl varsa etkin ACL kayıtlarını incele; sadece chmod sonucuna güvenme.', 'İlgili sistemde SELinux/AppArmor engellemesi olup olmadığını yetkili loglardan kontrol et.', 'Geniş chmod 777 veya kontrolsüz chown uygulama; gerekli en az yetkiyi onaylı biçimde tanımla.'), ('id', 'namei -l /HEDEF/YOL', 'getfacl /HEDEF/YOL'))

add('dns', 'dns_resolution', 'DNS: isim çözümleme ve kayıt hataları', 'Alan adı yanlış IP adresine çözümleniyor, NXDOMAIN dönüyor veya DNS sunucusu yanıt vermiyor olabilir.', ('NXDOMAIN, SERVFAIL, timeout veya yanlış IP sonucunu ayrı ayrı kaydet.', 'İstemcinin kullandığı DNS sunucusunu ve aranan tam alan adını belirle.', 'Kurumsal DNS ve yetkili DNS sunucularından sonuçları karşılaştır.', 'İsimle erişim ve IP ile erişim arasındaki farkı test et; IP erişiminin uygulama katmanını garanti etmediğini unutma.', 'DNS kaydı, TTL veya zone değiştirmeden önce kayıt sahibi ve değişiklik onayını doğrula.'), ('ipconfig /all', 'nslookup HEDEF_ALAN_ADI', 'Resolve-DnsName HEDEF_ALAN_ADI'))

add('dns', 'dns_service', 'DNS: sunucu erişimi ve DNS servisi', 'DNS sunucusu veya ağ yolu erişilemezse istemci çözümleme yapamayabilir.', ('Sorun tek istemcide mi yoksa aynı DNS sunucusunu kullanan herkeste mi kontrol et.', 'İstemcinin DNS sunucusuna ağ erişimini ve UDP/TCP 53 politikalarını yetkili ekiple incele.', 'İlgili DNS servisinin durumunu ve olay loglarını salt-okunur kontrol et.', 'Körlemesine DNS sunucusu değiştirme; şirket içi adların çözümlenmesini bozabilir.'), ('nslookup HEDEF_ALAN_ADI DNS_SUNUCUSU_IP',))

add('service', 'linux_service', 'Linux: systemd servis başlamıyor', 'Servis yapılandırması, bağımlılık, port çakışması veya izin hatası nedeniyle başarısız olabilir.', ('Servisin active, failed veya activating durumunu ve son çıkış kodunu incele.', 'journalctl ile ilgili servisin son hata satırlarını ve zamanını belirle.', 'Port dinleyicilerini ve yapılandırma doğrulama komutlarını servis özelinde kontrol et.', 'Son değişiklikleri ve bağımlı servisleri karşılaştır; rastgele restart uygulama.', 'Düzeltme öncesi yedek ve bakım onayını doğrula.'), ('systemctl status SERVIS_ADI', 'journalctl -u SERVIS_ADI -n 50 --no-pager', 'ss -ltnp'))

add('service', 'windows_service', 'Windows: servis başlamıyor', 'Windows servisi bağımlılık, kimlik bilgisi veya kaynak sorunu nedeniyle başlatılamayabilir.', ('Services konsolunda servis durumunu ve startup type değerini kontrol et.', 'Event Viewer System ve Application loglarında aynı zaman aralığındaki Service Control Manager olaylarını incele.', 'Servis hesabının durumunu, bağımlılıkları ve son değişiklikleri kontrol et.', 'Üretimde servis hesabı veya başlangıç türü değişikliğini onaysız yapma.'), ('Get-Service -Name SERVIS_ADI', 'Get-WinEvent -LogName System -MaxEvents 30'))

add('disk', 'disk_full', 'Disk: alan veya inode doluluğu', 'Dosya sistemi veya inode kapasitesi dolmuş olabilir.', ('df -h ve df -i çıktılarıyla kapasite ve inode kullanımını ayır.', 'Büyüyen dizinleri ve log dosyalarını belirle; mount noktalarını kontrol et.', 'Son büyüme zamanını, log rotasyonunu ve uygulama veri saklama politikasını incele.', 'Üretim verilerini veya logları onaysız silme; yedek ve saklama süresini doğrula.'), ('df -h', 'df -i', 'du -h -d 1 /var 2>/dev/null'))

add('wifi', 'wifi_connectivity', 'Ağ: Wi-Fi, DHCP ve ağ geçidi', 'Kablosuz bağlantı, IP dağıtımı veya ağ geçidi sorunu erişimi kesebilir.', ('Tek cihaz mı, tek SSID mi, tüm lokasyon mu etkilendi belirle.', 'IP, subnet mask, default gateway ve DNS değerlerini kontrol et.', 'DHCP lease, access point durumu ve bağlantı zamanını karşılaştır.', 'İstemci bağlantısını kontrollü yeniden dene; ağ cihazı konfigürasyonunu onaysız değiştirme.'), ('ipconfig /all', 'ping VARSAYILAN_AG_GECIDI'))

add('email', 'm365_access', 'Microsoft 365: Outlook / oturum açma', 'Lisans, MFA, hesap politikası veya hizmet kesintisi e-posta erişimini engelleyebilir.', ('Outlook masaüstü ve web erişimini karşılaştır; tam hata kodunu kaydet.', 'Microsoft 365 servis sağlığını ve yetkili oturum açma kayıtlarını kontrol et.', 'Kullanıcının lisans ve posta kutusu durumunu yetkili konsolda doğrula.', 'MFA sıfırlama veya lisans değişikliği için kimlik doğrulaması ve onay iste.'), ())

add('database', 'db_connections', 'Veritabanı: bağlantı sınırı / too many connections', 'Bağlantı havuzu, uzun süren oturumlar veya max_connections sınırı yeni bağlantıları engelleyebilir.', ('Hata mesajını, etkilenen uygulamayı ve veritabanı ürününü belirle.', 'PostgreSQL için yetkili salt-okunur oturumda bağlantı sayısını ve durum dağılımını incele.', 'Uygulama pool ayarlarını ve son deployment değişikliklerini karşılaştır.', 'Uzun süre idle in transaction oturumlarını araştır; sorgu veya bağlantı sonlandırmayı onaysız yapma.'), ('SELECT state, count(*) FROM pg_stat_activity GROUP BY state;', 'SHOW max_connections;'))

add('database', 'db_performance', 'Veritabanı: yavaş sorgu / kilit', 'Eksik indeks, kilit beklemesi veya kaynak darboğazı gecikmeye neden olabilir.', ('Yavaş sorgunun zamanını, etkilenen endpointi ve veritabanı sürümünü kaydet.', 'Yetkili salt-okunur izleme ekranında aktif sorgu ve bekleme türlerini incele.', 'CPU, disk IO ve bağlantı sayısını aynı zaman aralığında karşılaştır.', 'İndeks oluşturma veya sorgu değiştirme öncesinde DBA onayı ve performans değerlendirmesi al.'), ('SELECT pid, state, wait_event_type, wait_event FROM pg_stat_activity;',))

