_ALIASES = {'container_triage':'k8s_crash','vpn_auth':'vpn_auth','database_triage':'db_connections','cloud_triage':'cloud_iam','ci_cd_triage':'pipeline_fail','security_triage':'soc_alert','backup_triage':'backup_job','virtualization_triage':'vm_host','account_locked':'ad_lock','share_permission':'share_ntfs','linux_service':'linux_service','disk_full':'disk_full','wifi_connectivity':'wifi_connectivity','mail_access':'m365_access','dns_resolution':'dns_resolution','client_connection':'client_connection','web_service':'web_service','network_path':'network_path','access_policy':'access_policy'}
